import{_ as t,a0 as r,w as p,s as c,ao as l,I as i,x as n,a1 as o,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"如何使用 Linux anacron 命令 | LCTT x X-CMD","titleTemplate":false,"description":"如何使用 Linux anacron 命令 | LCTT (202104) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用 Linux anacron 命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用 Linux anacron 命令 | LCTT (202104) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202104/20210225 How to use the Linux anacron command","title":"如何使用 Linux anacron 命令","tag":"202104","desc":""},"relativePath":"202104/20210225 How to use the Linux anacron command.md","filePath":"[post].md"}'),d={name:"202104/20210225 How to use the Linux anacron command.md"};function h(u,a,b,g,k,m){const e=r("Link");return p(),c("div",null,[a[25]||(a[25]=l(`<h1 id="如何使用-linux-anacron-命令" tabindex="-1">如何使用 Linux anacron 命令 <a class="header-anchor" href="#如何使用-linux-anacron-命令" aria-label="Permalink to “如何使用 Linux anacron 命令”">​</a></h1><blockquote><p>與其手動執行重複性的任務，不如讓 Linux 為你做。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202104/06/084133bphrxxeolhoyqr0o.jpg" alt=""></p><p>在 2021 年，人們有更多的理由喜歡 Linux。在這個系列中，我將分享使用 Linux 的 21 個不同理由。自動化是使用 Linux 的最佳理由之一。</p><p>我最喜歡 Linux 的一個原因是它願意為我做工作。我不想執行重複性的任務，這些任務會佔用我的時間，或者容易出錯，或者我可能會忘記，我安排 Linux 為我做這些工作。</p><h3 id="為自動化做準備" tabindex="-1">為自動化做準備 <a class="header-anchor" href="#為自動化做準備" aria-label="Permalink to “為自動化做準備”">​</a></h3><p>“自動化”這個詞既讓人望而生畏，又讓人心動。我發現用模組化的方式來處理它是有幫助的。</p><h4 id="_1、你想實現什麼" tabindex="-1">1、你想實現什麼？ <a class="header-anchor" href="#_1、你想實現什麼" aria-label="Permalink to “1、你想實現什麼？”">​</a></h4><p>首先，要知道你想產生什麼結果。你是要給圖片加水印嗎？從雜亂的目錄中刪除文件？執行重要數據的備份？為自己明確定義任務，這樣你就知道自己的目標是什麼。如果有什麼任務是你發現自己每天都在做的，甚至一天一次以上，那麼它可能是自動化的候選者。</p><h4 id="_2、學習你需要的應用" tabindex="-1">2、學習你需要的應用 <a class="header-anchor" href="#_2、學習你需要的應用" aria-label="Permalink to “2、學習你需要的應用”">​</a></h4><p>將大的任務分解成小的組件，並學習如何手動但以可重複和可預測的方式產生每個結果。在 Linux 上可以做的很多事情都可以用腳本來完成，但重要的是要認識到你當前的侷限性。學習如何自動調整幾張圖片的大小，以便可以方便地通過電子郵件發送，與使用機器學習為你的每週通訊生成精心製作的藝術品之間有天壤之別。有的事你可以在一個下午學會，而另一件事可能要花上幾年時間。然而，我們都必須從某個地方開始，所以只要從小做起，並時刻注意改進的方法。</p><h4 id="_3、自動化" tabindex="-1">3、自動化 <a class="header-anchor" href="#_3、自動化" aria-label="Permalink to “3、自動化”">​</a></h4><p>在 Linux 上使用一個自動化工具來定期實現它。這就是本文介紹的步驟!</p><p>要想自動化一些東西，你需要一個腳本來自動化一個任務。在測試時，最好保持簡單，所以本文自動化的任務是在 <code>/tmp</code> 目錄下創建一個名為 <code>hello</code> 的文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/sh</span></span>
<span class="line"><span></span></span>
<span class="line"><span>touch /tmp/hello</span></span></code></pre></div><p>將這個簡單的腳本複製並粘貼到一個文本文件中，並將其命名為 <code>example</code>。</p><h3 id="cron" tabindex="-1">Cron <a class="header-anchor" href="#cron" aria-label="Permalink to “Cron”">​</a></h3>`,17)),i("p",null,[a[1]||(a[1]=n("每個安裝好的 Linux 系統都會有的內置自動化解決方案就是 cron 系統。Linux 用户往往把 cron 籠統地稱為你用來安排任務的方法（通常稱為 “cron 作業”），但有多個應用程序可以提供 cron 的功能。最通用的是 ",-1)),o(e,{href:"https://github.com/cronie-crond/cronie"},{default:s(()=>[...a[0]||(a[0]=[n("cronie",-1)])]),_:1}),a[2]||(a[2]=n("；它的優點是，它不會像歷史上為系統管理員設計的 cron 應用程序那樣，假設你的計算機總是開着。",-1))]),a[26]||(a[26]=l(`<p>驗證你的 Linux 發行版提供的是哪個 cron 系統。如果不是 cronie，你可以從發行版的軟件倉庫中安裝 cronie。如果你的發行版沒有 cronie 的軟件包，你可以使用舊的 anacron 軟件包來代替。<code>anacron</code> 命令是包含在 cronie 中的，所以不管你是如何獲得它的，你都要確保在你的系統上有 <code>anacron</code> 命令，然後再繼續。anacron 可能需要管理員 root 權限，這取決於你的設置。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ which anacron</span></span>
<span class="line"><span>/usr/sbin/anacron</span></span></code></pre></div><p>anacron 的工作是確保你的自動化作業定期執行。為了做到這一點，anacron 會檢查找出最後一次運行作業的時間，然後檢查你告訴它運行作業的頻率。</p><p>假設你將 anacron 設置為每五天運行一次腳本。每次你打開電腦或從睡眠中喚醒電腦時，anacron都會掃描其日誌以確定是否需要運行作業。如果一個作業在五天或更久之前運行，那麼 anacron 就會運行該作業。</p><h3 id="cron-作業" tabindex="-1">Cron 作業 <a class="header-anchor" href="#cron-作業" aria-label="Permalink to “Cron 作業”">​</a></h3><p>許多 Linux 系統都捆綁了一些維護工作，讓 cron 來執行。我喜歡把我的工作與系統工作分開，所以我在我的主目錄中創建了一個目錄。具體來説，有一個叫做 <code>~/.local</code> 的隱藏文件夾（“local” 的意思是它是為你的用户賬户定製的，而不是為你的“全局”計算機系統定製的），所以我創建了子目錄 <code>etc/cron.daily</code> 來作為 cron 在我的系統上的家目錄。你還必須創建一個 spool 目錄來跟蹤上次運行作業的時間。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mkdir -p ~/.local/etc/cron.daily ~/.var/spool/anacron</span></span></code></pre></div>`,7)),i("p",null,[a[4]||(a[4]=n("你可以把任何你想定期運行的腳本放到 ",-1)),a[5]||(a[5]=i("code",null,"~/.local/etc/cron.daily",-1)),a[6]||(a[6]=n(" 目錄中。現在把 ",-1)),a[7]||(a[7]=i("code",null,"example",-1)),a[8]||(a[8]=n(" 腳本複製到目錄中，然後 ",-1)),o(e,{href:"https://opensource.com/article/19/8/linux-chmod-command"},{default:s(()=>[...a[3]||(a[3]=[n("用 chmod 命令使其可執行",-1)])]),_:1}),a[9]||(a[9]=n("。",-1))]),a[27]||(a[27]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cp example ~/.local/etc/cron.daily</span></span>
<span class="line"><span># chmod +x ~/.local/etc/cron.daily/example</span></span></code></pre></div><p>接下來，設置 anacron 來運行位於 <code>~/.local/etc/cron.daily</code> 目錄下的任何腳本。</p><h3 id="anacron" tabindex="-1">anacron <a class="header-anchor" href="#anacron" aria-label="Permalink to “anacron”">​</a></h3><p>默認情況下，cron 系統的大部分內容都被認為是系統管理員的領域，因為它通常用於重要的底層任務，如輪換日誌文件和更新證書。本文演示的配置是為普通用户設置個人自動化任務而設計的。</p><p>要配置 anacron 來運行你的 cron 作業，請在 <code>/.local/etc/anacrontab</code> 創建一個配置文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>SHELL=/bin/sh</span></span>
<span class="line"><span>PATH=/sbin:/bin:/usr/sbin:/usr/bin</span></span>
<span class="line"><span>1  0  cron.mine    run-parts /home/tux/.local/etc/cron.daily/</span></span></code></pre></div><p>這個文件告訴 anacron 每到新的一天（也就是每日），延遲 0 分鐘後，就運行（<code>run-parts</code>）所有在 <code>~/.local/etc/cron.daily</code> 中找到的可執行腳本。有時，會使用幾分鐘的延遲，這樣你的計算機就不會在你登錄後就被所有可能的任務衝擊。不過這個設置適合測試。</p><p><code>cron.mine</code> 值是進程的一個任意名稱。我稱它為 <code>cron.mine</code>，但你也可以稱它為 <code>cron.personal</code> 或 <code>penguin</code> 或任何你想要的名字。</p><p>驗證你的 <code>anacrontab</code> 文件的語法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ anacron -T -t ~/.local/etc/anacrontab \\</span></span>
<span class="line"><span>  -S /home/tux/.var/spool/anacron</span></span></code></pre></div><p>沉默意味着成功。</p><h3 id="在-profile-中添加-anacron" tabindex="-1">在 .profile 中添加 anacron <a class="header-anchor" href="#在-profile-中添加-anacron" aria-label="Permalink to “在 .profile 中添加 anacron”">​</a></h3><p>最後，你必須確保 anacron 以你的本地配置運行。因為你是以普通用户而不是 root 用户的身份運行 anacron，所以你必須將它引導到你的本地配置：告訴 anacron 要做什麼的 <code>anacrontab</code> 文件，以及幫助 anacron 跟蹤每一個作業最後一次執行是多少天的 spool 目錄：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>anacron -fn -t /home/tux/.local/etc/anacrontab \\</span></span>
<span class="line"><span>  -S /home/tux/.var/spool/anacron</span></span></code></pre></div><p><code>-fn</code> 選項告訴 anacron <em>忽略</em> 時間戳，這意味着你強迫它無論如何都要運行你的 cron 作業。這完全是為了測試的目的。</p><h3 id="測試你的-cron-作業" tabindex="-1">測試你的 cron 作業 <a class="header-anchor" href="#測試你的-cron-作業" aria-label="Permalink to “測試你的 cron 作業”">​</a></h3><p>現在一切都設置好了，你可以測試作業了。從技術上講，你可以在不重啓的情況下進行測試，但重啓是最有意義的，因為這就是設計用來處理中斷和不規則的登錄會話的。花點時間重啓電腦、登錄，然後尋找測試文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls /tmp/hello</span></span>
<span class="line"><span>/tmp/hello</span></span></code></pre></div><p>假設文件存在，那麼你的示例腳本已經成功執行。現在你可以從 <code>~/.profile</code> 中刪除測試選項，留下這個作為你的最終配置。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>anacron -t /home/tux/.local/etc/anacrontab \\</span></span>
<span class="line"><span>  -S /home/tux/.var/spool/anacron</span></span></code></pre></div><h3 id="使用-anacron" tabindex="-1">使用 anacron <a class="header-anchor" href="#使用-anacron" aria-label="Permalink to “使用 anacron”">​</a></h3><p>你已經配置好了你的個人自動化基礎設施，所以你可以把任何你想讓你的計算機替你管理的腳本放到 <code>~/.local/etc/cron.daily</code> 目錄下，它就會按計劃運行。</p><p>這取決於你希望作業運行的頻率。示例腳本是每天執行一次。很明顯，這取決於你的計算機在任何一天是否開機和醒着。如果你在週五使用電腦，但把它設置在週末，腳本就不會在週六和週日運行。然而，在週一，腳本會執行，因為 anacron 會知道至少有一天已經過去了。你可以在 <code>~/.local/etc</code> 中添加每週、每兩週、甚至每月的目錄，以安排各種各樣的間隔。</p><p>要添加一個新的時間間隔：</p><ol><li>在 <code>~/.local/etc</code> 中添加一個目錄（例如 <code>cron.weekly</code>）。</li><li>在 <code>~/.local/etc/anacrontab</code> 中添加一行，以便在新目錄下運行腳本。對於每週一次的間隔，其配置如下。<code>7 0 cron.mine run-parts /home/tux/.local/etc/cron.weekly/</code>（<code>0</code> 的值可以選擇一些分鐘數，以適當地延遲腳本的啓動）。</li><li>把你的腳本放在 <code>cron.weekly</code> 目錄下。</li></ol><p>歡迎來到自動化的生活方式。它不會讓人感覺到，但你將會變得更有效率。</p><hr>`,27)),i("p",null,[a[11]||(a[11]=n("via: ",-1)),o(e,{href:"https://opensource.com/article/21/2/linux-automation"},{default:s(()=>[...a[10]||(a[10]=[n("https://opensource.com/article/21/2/linux-automation",-1)])]),_:1})]),i("p",null,[a[16]||(a[16]=n("作者：",-1)),o(e,{href:"https://opensource.com/users/seth"},{default:s(()=>[...a[12]||(a[12]=[n("Seth Kenlon",-1)])]),_:1}),a[17]||(a[17]=n(" 選題：",-1)),o(e,{href:"https://github.com/lujun9972"},{default:s(()=>[...a[13]||(a[13]=[n("lujun9972",-1)])]),_:1}),a[18]||(a[18]=n(" 譯者：",-1)),o(e,{href:"https://github.com/wxy"},{default:s(()=>[...a[14]||(a[14]=[n("wxy",-1)])]),_:1}),a[19]||(a[19]=n(" 校對：",-1)),o(e,{href:"https://github.com/wxy"},{default:s(()=>[...a[15]||(a[15]=[n("wxy",-1)])]),_:1})]),i("p",null,[a[22]||(a[22]=n("本文由 ",-1)),o(e,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...a[20]||(a[20]=[n("LCTT",-1)])]),_:1}),a[23]||(a[23]=n(" 原創編譯，",-1)),o(e,{href:"https://linux.cn/"},{default:s(()=>[...a[21]||(a[21]=[n("Linux中國",-1)])]),_:1}),a[24]||(a[24]=n(" 榮譽推出",-1))])])}const C=t(d,[["render",h]]);export{y as __pageData,C as default};
